// The bootstrap-replace scenario's steady state, once `ops` is retired: the same user,
// its keys declared as the list it holds. `keys.ts` is generated by the harness.

import type { ZapBuilder } from '../../../../../src/lib/zap.ts';
import { declare_replacement } from '../common.ts';
import { NEXT_USER_KEYS } from '../keys.ts';

export default (zap: ZapBuilder): void => {
	declare_replacement(zap, { keys: NEXT_USER_KEYS });
};
